  background: gray;
  border: 2px solid white;
}
.obj-bar .form-range::-moz-range-thumb {
  background: gray;
  border: 2px solid white;
}
.obj-bar .form-range::-ms-thumb {
  background: gray;
  border: 2px solid white;
}
.obj-bar .form-range::-webkit-slider-runnable-track {
  background: rgba(255,255,255, 0.5);
}
.obj-bar .form-range::-moz-range-track {
  background-color: rgba(255,255,255, 0.5);
}
.obj-bar-editable {
  color: white;
  background-color: rgba(255,255,255,0.2);
  border: none;
  text-align: center;
}
.obj-bar-editable::selection {
  background-color: gray;
  color: white;
}
.obj-bar-number {
  width: 40px;
  padding-left: 1px;
  padding-right: 1px;
  font-size: 15px;
}
.mq-cursor {
  border-color: white !important;
}
.info-icon {
  color: rgba(255, 255, 255, 0.6);
  padding-left:0px;
  padding-right:0px;
}
.obj-bar .form-switch .form-check-input {
  margin-top: 0px;
  background-color: rgba(255,255,255, 0.3);
  border: none;
  vertical-align: middle;
}
.obj-bar .form-switch .form-check-input {
  background-image: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
}
.obj-bar .form-switch .form-check-input:focus {
